#include <vector>
#include <numeric>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minOperations(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = accumulate(nums1.begin(), nums1.end(), 0LL);
        long long s2 = accumulate(nums2.begin(), nums2.end(), 0LL);
        if (s1 < s2) {
            swap(nums1, nums2);
            swap(s1, s2);
        }
        int diff = s1 - s2;
        if (diff == 0) return 0;

        vector<int> gains(6, 0);
        for (int x : nums1) gains[x - 1]++;
        for (int x : nums2) gains[6 - x]++;

        int ops = 0;
        for (int g = 5; g >= 1; --g) {
            if (gains[g] == 0) continue;
            int take = min(gains[g], (diff + g - 1) / g);
            ops += take;
            diff -= take * g;
            if (diff <= 0) return ops;
        }
        return -1;
    }
};

class Solution {
    public int minOperations(int[] nums1, int[] nums2) {
        long s1 = 0, s2 = 0;
        for (int x : nums1) s1 += x;
        for (int x : nums2) s2 += x;
        if (s1 < s2) {
            int[] t = nums1; nums1 = nums2; nums2 = t;
            long ts = s1; s1 = s2; s2 = ts;
        }
        int diff = (int)(s1 - s2);
        if (diff == 0) return 0;

        int[] gains = new int[6];
        for (int x : nums1) gains[x - 1]++;
        for (int x : nums2) gains[6 - x]++;

        int ops = 0;
        for (int g = 5; g >= 1; --g) {
            if (gains[g] == 0) continue;
            int take = Math.min(gains[g], (diff + g - 1) / g);
            ops += take;
            diff -= take * g;
            if (diff <= 0) return ops;
        }
        return -1;
    }
}

