var minOperations = function(nums1, nums2) {
    let s1 = nums1.reduce((a, b) => a + b, 0);
    let s2 = nums2.reduce((a, b) => a + b, 0);
    if (s1 < s2) {
        [nums1, nums2] = [nums2, nums1];
        [s1, s2] = [s2, s1];
    }
    let diff = s1 - s2;
    if (diff === 0) return 0;

    const gains = Array(6).fill(0);
    for (const x of nums1) gains[x - 1]++;
    for (const x of nums2) gains[6 - x]++;

    let ops = 0;
    for (let g = 5; g >= 1; --g) {
        if (gains[g] === 0) continue;
        const take = Math.min(gains[g], Math.floor((diff + g - 1) / g));
        ops += take;
        diff -= take * g;
        if (diff <= 0) return ops;
    }
    return -1;
};
